/** One path that answers to more than one method. */
function operations(summaries: Readonly<Record<string, string>>): Record<string, unknown> {
  return Object.assign(
    {},
    ...Object.entries(summaries).map(([method, summary]) => operation(method, summary)),
  ) as Record<string, unknown>;
}

function reservationResponse(description: string) {
  return {
    description,
    content: {
      "application/json": {
        schema: { $ref: "#/components/schemas/WorkerEndpointOriginReservation" },
      },
    },
  } as const;
}

function currentReservationResponse(description: string) {
  return {
    description,
    content: {
      "application/json": {
        schema: { $ref: "#/components/schemas/WorkerEndpointOriginReservationV2" },
      },
    },
  } as const;
}

function reservationActivationOperation(summary: string) {
  return {
    summary,
    parameters: [RESERVATION_ID_PARAMETER],
    requestBody: {
      required: true,
      content: {
        "application/json": {
          schema: {
            $ref: "#/components/schemas/WorkerEndpointOriginReservationActivationRequest",
          },
        },
      },
    },
    responses: {
      "200": reservationResponse("Updated reservation projection"),
      "400": errorResponse("Malformed or open request"),
      "401": errorResponse("Organization API key required"),
      "403": errorResponse("The key lacks resources:write"),
      "404": errorResponse("Reservation not found"),
      "409": errorResponse("Endpoint identity, relation, readiness, origin, or placement conflict"),
      "503": errorResponse("Reservation or Resource authority unavailable"),
    },
  } as const;
}

function runtimeInputPathParameters() {
  return [
    {
      name: "operationKey",
      in: "path",
      required: true,
      schema: OPERATION_KEY_SCHEMA,
    },
    {
      name: "Idempotency-Key",
      in: "header",
      required: true,
      description: "Must equal the operation key in the path.",
      schema: OPERATION_KEY_SCHEMA,
    },
  ] as const;
}

/**
 * One documented failure.
 *
 * Every error on the control lane and the Takoform Host lane is the same
 * closed envelope, so the document pins its shape rather than leaving the
 * status with a description and no schema. The released provider decodes an
 * envelope only when `code`, `message`, `requestId` and `retryable` are all
 * present; an undocumented shape is how a lane came to answer two members and
 * make its own 404 unreadable.
 */
function errorResponse(description: string) {
  return {
    description,
    content: { "application/json": { schema: { $ref: "#/components/schemas/Error" } } },
  } as const;
}

function runtimeInputResponse(description: string) {
  return {
    description,
    content: {
      "application/json": {
        schema: { $ref: "#/components/schemas/WorkerRuntimeInputPreparation" },
      },
    },
  } as const;
}

function operation(
  method: string,
  summary: string,
  extra: {
    readonly security?: readonly unknown[];
    readonly parameters?: readonly unknown[];
  } = {},
): Record<string, unknown> {
  return {
    [method]: {
      summary,
      responses: { "200": { description: "Success" } },
      ...(extra.security ? { security: extra.security } : {}),
      ...(extra.parameters ? { parameters: extra.parameters } : {}),
    },
  };
}

function takoformPaths(): Record<string, Record<string, unknown>> {
  const paths: Record<string, Record<string, unknown>> = {};
  for (const lane of TAKOFORM_LANES) {
    for (const entry of TAKOFORM_PATHS) {
      const methods: Record<string, unknown> = {};
      for (const { method, summary } of entry.methods) {
        methods[method] = { summary, responses: { "200": { description: "Success" } } };
      }
      paths[`/apis/forms.takoform.com/${lane}${entry.path}`] = methods;
    }
  }
  return paths;
}

